fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    if n <= 1 {
        // For n = 0: returns ([], [])
        // For n = 1: returns ([a[0]], [])
        return (a, Vec::new());
    }

    // Split into two non-empty parts so both are strictly shorter than `a`.
    let mid = n / 2; // with n > 1, mid is in [1, n-1]
    let mut left = a;
    let right = left.split_off(mid); // left keeps [0..mid), right gets [mid..n)
    (left, right)
}